const fs=require('node:fs'),path=require('node:path');async function main(){
 const pages=(await(await fetch('http://127.0.0.1:57221/json/list')).json()).filter(t=>t.type==='page'&&t.url.includes('/apps/pc-app/dist/ui/index.html'));if(pages.length!==1)throw Error('Unique original B2 renderer required');
 const expression=`(()=>{const rect=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};const a=document.activeElement;return {route:location.hash,selected:[...document.querySelectorAll('.resource-card[aria-pressed=true]')].map(e=>({resourceId:e.getAttribute('data-resource-id'),text:e.innerText,rect:rect(e)})),visibleCards:[...document.querySelectorAll('.resource-card')].map(e=>({resourceId:e.getAttribute('data-resource-id'),text:e.innerText,rect:rect(e)})),active:{tag:a.tagName,role:a.getAttribute('role'),label:a.getAttribute('aria-label'),value:a.getAttribute('aria-valuenow'),rect:rect(a)},sliders:[...document.querySelectorAll('[role=slider]')].map(e=>({label:e.getAttribute('aria-label'),value:e.getAttribute('aria-valuenow'),min:e.getAttribute('aria-valuemin'),max:e.getAttribute('aria-valuemax'),rect:rect(e)})),calibration:[...document.querySelectorAll('.resource-slider')].map(e=>e.innerText),context:[...document.querySelectorAll('[role=combobox]')].map(e=>({label:e.getAttribute('aria-label'),text:e.innerText})),errors:[...document.querySelectorAll('[role=alert]')].map(e=>e.innerText),messages:[...document.querySelectorAll('[role=status]')].map(e=>e.innerText),buttons:[...document.querySelectorAll('button')].filter(e=>/保存动作|放弃/.test(e.innerText)).map(e=>({text:e.innerText,disabled:e.disabled}))}})()`;
 const ws=new WebSocket(pages[0].webSocketDebuggerUrl);const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ws.close();reject(Error('Readonly timeout'));},10000);ws.onopen=()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{returnByValue:true,expression}}));ws.onerror=()=>{clearTimeout(timer);reject(Error('Readonly connection failed'));};ws.onmessage=e=>{const r=JSON.parse(e.data);if(r.id!==1)return;clearTimeout(timer);ws.close();if(r.error||r.result?.exceptionDetails)reject(Error('Readonly DOM projection failed'));else resolve(r.result.result.value);};});
 const report={at:new Date().toISOString(),method:'Readonly public resource DOM/ARIA and visible calibration only; no business API/input/mutation/credential values',result};const output=path.join(__dirname,'cloudB2-resource-public-ui-'+process.argv[2]+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,...report}));
}main().catch(e=>{console.error(e.message);process.exitCode=1;});
